import sys
input = sys.stdin.read
data = input().split()

n, s, k = map(int, data[:3])
candies = list(map(int, data[3:n+3]))
colors = data[n+3]

dp = [[-1] * (k+1) for _ in range(n)]
for i in range(n):
    if colors[i] == colors[s-1]:
        dp[i][candies[i]] = abs(i-s+1)

for i in range(n):
    for j in range(k+1):
        if dp[i][j] == -1:
            continue
        for ni in range(n):
            if colors[i] == colors[ni] or candies[i] >= candies[ni]:
                continue
            nj = j + candies[ni]
            if nj > k:
                continue
            if dp[ni][nj] == -1 or dp[ni][nj] > dp[i][j] + abs(ni-i):
                dp[ni][nj] = dp[i][j] + abs(ni-i)

ans = min(dp[n-1])
print(ans)

